import { describe, expect, it } from "vitest";
import { feelsLike } from "./feels-like";
import fixture from "./metpy-heat-index.fixture.json";

// Heat index from metpy.calc.heat_index (MetPy 1.7.1), generated by
// apps/api/fastapi/scripts/metpy_fixtures.py. Air temperature 80 F and above.
const TOLERANCE_C = 0.001;

describe("feelsLike against MetPy's heat index", () => {
  it("agrees with every fixture point within a millidegree", () => {
    expect(fixture.points.length).toBeGreaterThan(200);
    for (const point of fixture.points) {
      const ours = feelsLike(point.airC, point.relativeHumidity);
      expect(
        Math.abs(ours - point.heatIndexC),
        `${point.airC} °C at ${point.relativeHumidity} %`
      ).toBeLessThanOrEqual(TOLERANCE_C);
    }
  });

  it("applies the heat index from 80 °F, not from 27 °C", () => {
    // 26.7 °C is 80.1 °F: the NWS heat index applies and reads well above the air.
    expect(feelsLike(26.7, 100)).toBeGreaterThan(30);
  });
});

describe("feelsLike outside the heat index", () => {
  it("is the air temperature below 80 °F", () => {
    expect(feelsLike(26.5, 100)).toBe(26.5); // 79.7 °F
    expect(feelsLike(20, 90)).toBe(20);
  });

  it("is the air temperature when humidity is unknown", () => {
    expect(feelsLike(30, null)).toBe(30);
  });
});

it("falls back to the air temperature when humidity cannot be read", () => {
  expect(feelsLike(32, Number.NaN)).toBe(32);
  expect(feelsLike(32, Number.POSITIVE_INFINITY)).toBe(32);
});
